public class Demo {
    public static void main(String[] args) {
        int i = 1;
        do {
            System.out.println(i);
            i++;
        } while (i <= 5);
    }
}

import java.util.Scanner;

public class Demo {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        System.out.print("Enter two numbers: ");
        int n = sc.nextInt();
        int m = sc.nextInt();

        while (m != 0) {
            int r = n % m;
            n = m;
            m = r;
        }
        System.out.println("GCD = " + n);
    }
}

import java.util.Scanner;

class GCD {
    int findGcd(int n, int m) {
        while (m != 0) {
            int r = n % m;
            n = m;
            m = r;
        }
        return n;
    }
}

public class Demo {
